if not(Bj and Cj)then
return false
end
local Dj,Ej=pcall(H.PSC.check_if_unlocked_level,Bj,Cj)
return Dj and Ej and true or false
end
function O.artifactLeft(Fj)
local Gj,Hj,Ij=H.Levels[Fj],J.live.artifact or{},H.prof()
local Jj=Ij and Ij.artifact_data
if not(type(Jj)==ioc[1408]and Jj._interval==Hj.interval)and type(Hj.ad)==ioc[1408]then
Jj=Hj.ad
end
local Kj=type(Jj)==ioc[1408]and Hj.interval~=nil and Jj._interval==Hj.interval
local Lj=Kj and type(Jj._completed)==ioc[1408]and Jj._completed[Fj]
local Mj=type(Lj)==ioc[1408]and type(Lj.difficulty_completed_data)==ioc[1408]and Lj.difficulty_completed_data.Hard
local Nj=type(Mj)==ioc[1408]and tonumber(Mj.times_completed)or 0
local Oj=Kj and type(Jj._clear_rewards)==ioc[1408]and type(Jj._clear_rewards[Fj])==ioc[1408]and Jj._clear_rewards[Fj].Hard or{}
local Pj,Qj=0,0
for Rj,Sj in pairs(Gj and Gj.clear_rewards and Gj.clear_rewards.Hard or{})do
local Tj=tonumber(Sj.clears)or 0
if Tj>Qj then
Qj=Tj
end
if Tj>Nj and not Oj[Sj._id]then
local Uj=Sj.reward or{}
Pj=Pj+(tonumber(Uj.gem_reward)or 0)
for Vj,Wj in ipairs(M.list(Uj.item))do
if type(Wj)==ioc[1408]and Wj.item_id then
Pj=Pj+O.itemValue(Wj.item_id,tonumber(Wj.amount)or 1)
end
end
end
end
return Nj,Pj,Qj,Oj
end
