function eb.weatherStrength(om)
local pm=eb.fx(om)
local qm=pm.dmg/pm.cd/pm.hp/pm.speed*(1+(pm.range-1)/2)
for rm,sm in pairs(pm.kinds)do
qm=qm*(1+Q.rogueShare(rm)*sm)
end
if pm.ice>0 then
local tm=Q.rogueShare(ioc[1586])
qm=qm*(tm+(1-tm)/(1-pm.ice+pm.ice/W.modFactor(ioc[1615])))
end
if pm.fly>0 then
qm=qm*(1-pm.fly*0.5)
end
if pm.noCC then
qm=qm*0.95
end
if pm.shroud then
qm=qm*0.9
end
return qm
end
