else
table.insert(ot,qt)
end
end
end
if#nt>0 then
ct={}
if mt then
table.insert(ct,mt)
end
for rt,tt in ipairs(nt)do
table.insert(ct,tt)
end
for ut,vt in ipairs(ot)do
table.insert(ct,vt)
end
end
end
for wt,xt in ipairs(ct)do
if xt.kind==ioc[1561]then
local yt=ct[1]
if wt>1 and yt.kind~=ioc[1559]and not(yt.kind==ioc[1428]and yt.started)then
table.remove(ct,wt)
table.insert(ct,1,xt)
xt.why=ioc[1765]..(xt.why or ioc[337])
end
break
end
end
for zt,At in ipairs(ct)do
if At.kind==ioc[1560]then
local Bt=ct[1]
if zt>1 and(At.p or 0)>=0.25 and Bt.kind~=ioc[1559]and Bt.kind~=ioc[1561]and not(Bt.kind==ioc[1428]and Bt.started)and not tostring(Bt.why):find(ioc[1766],1,true)then
table.remove(ct,zt)
table.insert(ct,1,At)
At.why=ioc[1767]..(At.why or ioc[337])
end
break
end
end
local Ct=ct[1]
if Ct and Ct.kind==ioc[1443]and Ct.first then
local Dt,Et=Ct,(Ct.baseScore or Ct.score)*O.CHAIN_MIN
for Ft=1,6 do
local Gt
for Ht,It in ipairs(ct)do
if It.kind==ioc[1443]and It.first and It.diff==Dt.diff and(It.baseScore or It.score)>=Et and O.nextAct(It.level)==Dt.level then
Gt=It
break
end
end
if not Gt then
break
end
Dt=Gt
end
if Dt~=Ct then
table.remove(ct,table.find(ct,Dt))
table.insert(ct,1,Dt)
Dt.why=ioc[1768]..(Dt.why or ioc[337])
end
end
local Jt=J.testTeam
if Jt and(Jt.left or 0)>0 then
for Kt,Lt in ipairs(ct)do
