local rB=ab.goals()
local sB=table.clone(rB)
table.sort(sB,function(tB,uB)
local vB,wB=tonumber(tB.tierRank)or 0,tonumber(uB.tierRank)or 0
if vB~=wB then
return vB>wB
end
local xB,yB=tonumber(tB.scoreFull)or 0,tonumber(uB.scoreFull)or 0
if xB~=yB then
return xB>yB
end
return tostring(tB.uuid)<tostring(uB.uuid)
end)
J.goalsTop={}
for zB,AB in ipairs(sB)do
if zB<=10 or AB.pinned then
table.insert(J.goalsTop,{uuid=AB.uuid,from=AB.from,to=AB.to,ready=AB.ready,intoTeam=AB.intoTeam,unknown=AB.unknown,hidden=AB.hidden,pinned=AB.pinned,text=ab.text(AB)})
end
end
J.goals={}
table.clear(J.goalItems)
table.clear(J.goalNeed)
local BB=0
local CB=rB[1]and rB[1].pinned
for DB,EB in ipairs(rB)do
table.insert(J.goals,{uuid=EB.uuid,from=EB.from,to=EB.to,ready=EB.ready,intoTeam=EB.intoTeam,unknown=EB.unknown,hidden=EB.hidden,tierRank=EB.tierRank,text=ab.text(EB),gain=EB.gain,runs=EB.runs,plans=EB.plans,items=EB.items,eats=EB.eats,scoreFrom=EB.scoreFrom,scoreTo=EB.scoreTo,pinned=EB.pinned})
if not EB.ready and(EB.pinned or(not CB and I.goals and not EB.unknown and(not EB.hidden or EB.intoTeam)and(EB.intoTeam or BB==0)and BB<2))then
BB=BB+1
for FB,GB in ipairs(EB.plans)do
if GB.farm and GB.farmNeed>0 then
local HB=I.goalValue*(EB.intoTeam and 1 or 0.4)/(BB==1 and 1 or 2)/math.max(1,GB.farmNeed)
J.goalItems[GB.farm]=math.max(J.goalItems[GB.farm]or 0,HB)
J.goalNeed[GB.farm]=math.max(J.goalNeed[GB.farm]or 0,GB.farmNeed)
