if NB and ab.have(LB.costItem)<MB then
R.add((H.Items[LB.item]or{}).name or LB.item,LB.cost,(H.Items[LB.costItem]or{}).name or LB.costItem,ioc[1869]..N.name(JB.to))
if j.notify then
j.notify(ioc[1870],string.format(ioc[1871],(H.Items[LB.item]or{}).name or LB.item,N.name(JB.from)),ioc[1824])
end
return true
else
j.log(1,ioc[1825],ioc[1872]..tostring(LB.shopKey)..ioc[1704]..tostring(OB)..ioc[1705])
j.backoff(ioc[1867],900)
