return 0
end
local dE,eE=0,0
for fE,gE in pairs(_D._core_damage_type_buffs or{})do
if bE[gE.damage_type]then
dE=dE+(tonumber(gE.mul)or 0)+(tonumber(gE.add_upg)or 0)*0.01+(tonumber(gE.pen)or 0)*0.001
eE=eE+(tonumber(gE.crit)or 0)
end
end
dE=dE+eE*0.5
local hE=N.rows(YD.unit_id)
local iE=hE and hE[hE.max]
local jE=(iE and tonumber(iE.cd)or 0)*N.mult(YD,ioc[1542])
for kE,lE in pairs(_D._unique_relic_effects or{})do
local mE=type(lE.params)==ioc[1408]and lE.params or{}
