local nE=math.min(1,(tonumber(mE.extra_damage)or 0)*jE/math.max(1,tonumber(mE.time_interval)or 40))
local oE=N.DRONES and N.DRONES[YD.unit_id]
if oE and oE.late and jE>0 then
local pE=1/jE
nE=nE*pE/(pE+(tonumber(oE.max)or 0)*(tonumber(oE.late.dmg)or 0)*(tonumber(oE.hits)or 1)/math.max(0.1,tonumber(oE.late.cd)or 4))
end
dE=dE+nE
elseif lE.id==ioc[1892]then
dE=dE+(tonumber(mE.dmg_buff)or 0)*0.25
elseif lE.id==ioc[1893]then
dE=dE+(tonumber(mE.dmg_buff)or 0)*eE
elseif lE.id==ioc[1894]then
if bE.magic then
dE=0
else
dE=dE+(tonumber(mE.dmg_buff)or 0)*0.3
end
elseif lE.id==ioc[1895]then
if bE.water_damage then
dE=dE+0.05
end
end
end
return dE
end
