return 0
end
local FNb=0
for GNb,HNb in ipairs(Q.mine or{})do
local INb=HNb._stats
local JNb=N.rows(INb.id.Value)
local KNb=JNb and JNb[math.min(INb.upgrade.Value,JNb.max)]
local LNb=KNb and KNb.atk and N.attackInfo(KNb.atk,KNb.range)
if LNb and((LNb.stun or 0)>0 or(LNb.slowTime or 0)>0)then
FNb=FNb+1
end
end
local MNb,NNb=W.mask(Q.info.map,N.range(CNb.u,0)*(Q.info.rangeScale or 1)),0
for ONb=1,W.BINS do
if MNb[ONb]then
NNb=NNb+1
end
end
local PNb=Q.depth and Q.depth.units>0 and Q.depth.covEnd or 1
local QNb=(N.airFrom(CNb.id)==0)and 1 or(1-(1-H.FLY_GROUND)*math.min(1,Q.info.flyChance or 0))
