function Q.learn()
local LUb,MUb={},{}
local NUb,OUb=0,0
for PUb,QUb in ipairs(Q.mine)do
local RUb=QUb._stats
local SUb=RUb.id.Value
local TUb=RUb:FindFirstChild(ioc[2790])and RUb.total_damage.Value or 0
if not N.isFarm(SUb)then
LUb[SUb]=(LUb[SUb]or 0)+TUb
MUb[SUb]=(MUb[SUb]or 0)+Q.liveDps(QUb,SUb)/math.max(0.5,N.nudge(SUb))
local UUb=N.passive(SUb).mark
if UUb then
MUb[SUb]=MUb[SUb]+UUb.dot*RUb.damage.Value
end
NUb=NUb+TUb
end
end
for VUb,WUb in pairs(MUb)do
OUb=OUb+WUb
end
if NUb<=0 or OUb<=0 then
return
end
Q.lastEff={}
for XUb,YUb in pairs(LUb)do
local ZUb,_Ub=YUb/NUb,MUb[XUb]/OUb
if _Ub>0.02 then
local aVb=J.learn[XUb]or{eff=1,n=0}
local bVb=math.max(0.02,0.25*math.sqrt(30/(30+aVb.n)))
local cVb=M.clamp(ZUb/_Ub,0.3,3)
Q.lastEff[XUb]=math.floor(cVb*1000+0.5)/1000
aVb.eff=aVb.eff+(cVb-aVb.eff)*bVb
aVb.n=aVb.n+1
J.learn[XUb]=aVb
end
end
end
